// Flat native-message JSON codec using only .NET 2.0 core APIs.
// Browser commands contain scalar properties. Nested objects are rejected.
using System;
using System.Text;
using System.Collections.Generic;
using System.Globalization;
using System.Reflection;
class MiniJson {
 string text;int position;
 void Space(){while(position<text.Length&&Char.IsWhiteSpace(text[position]))position++;}
 void Token(char c){Space();if(position>=text.Length||text[position++]!=c)throw new FormatException("Invalid JSON token.");}
 string StringValue(){Token('"');StringBuilder b=new StringBuilder();while(position<text.Length){char c=text[position++];if(c=='"')return b.ToString();if(c<32)throw new FormatException("Invalid JSON string.");if(c!='\\'){b.Append(c);continue;}if(position>=text.Length)break;c=text[position++];switch(c){case '"':case '\\':case '/':b.Append(c);break;case 'b':b.Append('\b');break;case 'f':b.Append('\f');break;case 'n':b.Append('\n');break;case 'r':b.Append('\r');break;case 't':b.Append('\t');break;case 'u':if(position+4>text.Length)throw new FormatException("Invalid Unicode escape.");b.Append((char)UInt16.Parse(text.Substring(position,4),NumberStyles.HexNumber,CultureInfo.InvariantCulture));position+=4;break;default:throw new FormatException("Invalid JSON escape.");}}throw new FormatException("Unclosed JSON string.");}
 object Value(){Space();if(position>=text.Length)throw new FormatException("Missing JSON value.");if(text[position]=='"')return StringValue();if(text.Substring(position).StartsWith("true",StringComparison.Ordinal)){position+=4;return true;}if(text.Substring(position).StartsWith("false",StringComparison.Ordinal)){position+=5;return false;}if(text.Substring(position).StartsWith("null",StringComparison.Ordinal)){position+=4;return null;}int start=position;if(text[position]=='-')position++;int digits=position;while(position<text.Length&&text[position]>='0'&&text[position]<='9')position++;if(position==digits||(position-digits>1&&text[digits]=='0'))throw new FormatException("Invalid JSON number.");return Int64.Parse(text.Substring(start,position-start),CultureInfo.InvariantCulture);}
 public Dictionary<string,object> Deserialize(string input){text=input;position=0;Dictionary<string,object> result=new Dictionary<string,object>();Token('{');Space();if(position<text.Length&&text[position]=='}')position++;else while(true){string key=StringValue();Token(':');if(result.ContainsKey(key))throw new FormatException("Duplicate JSON key.");result.Add(key,Value());Space();if(position>=text.Length)throw new FormatException("Unclosed JSON object.");char c=text[position++];if(c=='}')break;if(c!=',')throw new FormatException("Invalid JSON separator.");}Space();if(position!=text.Length)throw new FormatException("Extra JSON data.");return result;}
 static string Quote(string s){StringBuilder b=new StringBuilder("\"");foreach(char c in s){if(c=='"'||c=='\\'){b.Append('\\');b.Append(c);}else if(c<32){b.Append("\\u");b.Append(((int)c).ToString("x4",CultureInfo.InvariantCulture));}else b.Append(c);}b.Append('"');return b.ToString();}
 public string Serialize(object value){StringBuilder b=new StringBuilder("{");bool first=true;foreach(PropertyInfo property in value.GetType().GetProperties()){if(!first)b.Append(',');first=false;b.Append(Quote(property.Name));b.Append(':');object scalar=property.GetValue(value,null);if(scalar==null)b.Append("null");else if(scalar is string)b.Append(Quote((string)scalar));else if(scalar is bool)b.Append((bool)scalar?"true":"false");else b.Append(Convert.ToString(scalar,CultureInfo.InvariantCulture));}b.Append('}');return b.ToString();}
}
